// Pine Script v5 - Simple SMA crossover buy/sell indicator
// Based on a short-term (50) / long-term (200) moving average crossover
//@version=5
indicator("AI Buy/Sell Indicator - SMA Crossover", overlay=true)

// Inputs
shortPeriod = input.int(50, title="Short SMA Period", minval=1)
longPeriod  = input.int(200, title="Long SMA Period", minval=1)
src         = input.source(close, "Source")
showLabels  = input.bool(true, "Show Buy/Sell Labels")
showLines   = input.bool(true, "Show SMA Lines")

// Moving averages
smaShort = ta.sma(src, shortPeriod)
smaLong  = ta.sma(src, longPeriod)

// Plot SMAs
if showLines
    plot(smaShort, title="SMA Short", color=color.orange, linewidth=2)
    plot(smaLong,  title="SMA Long",  color=color.blue,   linewidth=2)

// Generate signals: buy when short SMA crosses above long SMA, sell when it crosses below
buySignal  = ta.crossover(smaShort, smaLong)
sellSignal = ta.crossunder(smaShort, smaLong)

// Plot buy/sell shapes on chart
plotshape(buySignal,  title="Buy Signal",  location=location.belowbar, color=color.green, style=shape.triangleup,   size=size.small, text=showLabels ? "BUY" : "")
plotshape(sellSignal, title="Sell Signal", location=location.abovebar, color=color.red,   style=shape.triangledown, size=size.small, text=showLabels ? "SELL" : "")

// Alert conditions so you can create TradingView alerts
alertcondition(buySignal,  title="Buy Alert",  message="SMA crossover BUY (short SMA crossed above long SMA)")
alertcondition(sellSignal, title="Sell Alert", message="SMA crossover SELL (short SMA crossed below long SMA)")

// Optional: draw background color to indicate trend
bgcolor(ta.valuewhen(buySignal, color.new(color.green, 90), 0) ? color.new(color.green, 90) : na, transp=100)

// Notes:
// - This script implements the same simple moving-average crossover approach described earlier
//   (short-term SMA crossing above/below long-term SMA = buy/sell).
